      { q: L('7 + 9 + 3 + 1 = ?', '7 + 9 + 3 + 1 = ?', '7 + 9 + 3 + 1 = ?'), s: L('Ikki juft do‘st son: (7 + 3) + (9 + 1) = 10 + 10 = <b>20</b>.', 'Две пары друзей: (7 + 3) + (9 + 1) = 10 + 10 = <b>20</b>.', 'Two pairs of friends: (7 + 3) + (9 + 1) = 10 + 10 = <b>20</b>.') }
